head.script:
scwin.trigger1_onclick = function(e) {
    tabControl1.deleteAllTabs();
};
scwin.isDeleteAll = function() {
    return WebSquare.wUnit.getDomById('tabControl1_tabhost').getElementsByTagName("li").length == 0;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Script 탭 또는 Source 탭에서 scwin.trigger1_onclick 부분을 확인한다.
    //1. In the Script tab or the Source tab, check the scwin.trigger1_onclick section.
    // verify step 1. tabControl1.deleteAllTabs();
    //Test step 2. 브라우저에서 deleteAllTabs 버튼을 클릭한다.
    //2. Click the deleteAllTabs button in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 열려있는 모든 Tab 이 닫힌다. (없어진다.)
    //2. All open Tabs are closed. (Disappears)
    WebSquare.wUnit.addCommand("assert", "scwin.isDeleteAll()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 30-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
